schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://dual-write-shadow-read-template/output.schema.json",
  "title": "Dual-write + shadow-read migration runbook",
  "type": "object",
  "required": [
    "migration_name", "kind", "old_store", "new_store", "entity_types", "dual_write",
    "reconciliation", "backfill", "shadow_read", "flags", "cutover", "evidence"
  ],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "flag_name": {"type": "string", "pattern": "^[a-z][a-z0-9_.-]*$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "migration_name": {"type": "string", "minLength": 3},
    "kind": {"type": "string", "enum": ["postgres-major-upgrade", "monolith-to-service-split", "schema-rewrite", "datastore-swap", "other"]},
    "old_store": {"type": "string", "minLength": 2},
    "new_store": {"type": "string", "minLength": 2},
    "entity_types": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "primary_key", "version_field", "parity_excluded_fields", "gate"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "primary_key": {"type": "string", "minLength": 1},
          "version_field": {"type": "string", "minLength": 1, "description": "row version, updated_at, or log sequence number"},
          "parity_excluded_fields": {"type": "array", "items": {"type": "string", "minLength": 1}},
          "gate": {
            "type": "object",
            "required": ["mismatch_ratio_max", "window_hours", "min_comparisons"],
            "additionalProperties": false,
            "properties": {
              "mismatch_ratio_max": {"type": "number", "minimum": 0, "exclusiveMaximum": 1},
              "window_hours": {"type": "integer", "minimum": 1},
              "min_comparisons": {"type": "integer", "minimum": 1}
            }
          }
        }
      }
    },
    "dual_write": {
      "type": "object",
      "required": ["upsert_kind", "compare_and_set_on_version", "outside_old_store_transaction", "failure_fails_user_request", "retry_queue", "failure_metric", "alert_threshold"],
      "additionalProperties": false,
      "properties": {
        "upsert_kind": {"type": "string", "const": "version-guarded-upsert"},
        "compare_and_set_on_version": {"type": "boolean", "const": true},
        "outside_old_store_transaction": {"type": "boolean", "const": true},
        "failure_fails_user_request": {"type": "boolean", "const": false},
        "retry_queue": {"type": "string", "minLength": 2},
        "failure_metric": {"type": "string", "const": "dual_write_failures_total"},
        "alert_threshold": {"type": "number", "exclusiveMinimum": 0}
      }
    },
    "reconciliation": {
      "type": "object",
      "required": ["job_name", "cadence", "max_repairs_per_run", "metric", "declared_before_dual_write"],
      "additionalProperties": false,
      "properties": {
        "job_name": {"type": "string", "minLength": 2},
        "cadence": {"type": "string", "enum": ["every-5-minutes", "hourly", "every-6-hours", "daily", "weekly"]},
        "max_repairs_per_run": {"type": "integer", "minimum": 0},
        "metric": {"type": "string", "const": "reconciliation_repairs_total"},
        "declared_before_dual_write": {"type": "boolean", "const": true}
      }
    },
    "backfill": {
      "type": "object",
      "required": ["starts_after_dual_write", "uses_same_upsert", "per_partition_counts_match", "checksum_match", "completed_before_shadow_parity"],
      "additionalProperties": false,
      "properties": {
        "starts_after_dual_write": {"type": "boolean", "const": true},
        "uses_same_upsert": {"type": "boolean", "const": true},
        "per_partition_counts_match": {"type": "boolean", "const": true},
        "checksum_match": {"type": "boolean", "const": true},
        "completed_before_shadow_parity": {"type": "boolean", "const": true},
        "partitions": {"type": "integer", "minimum": 1}
      }
    },
    "shadow_read": {
      "type": "object",
      "required": ["comparator", "returns_old_store_result", "candidate_timeout_ms", "old_store_p99_ms", "exceptions_swallowed_and_counted", "sampling_flag", "sampling_percent_initial", "mismatch_metric", "mismatch_samples_retained"],
      "additionalProperties": false,
      "properties": {
        "comparator": {"type": "string", "const": "normalising"},
        "returns_old_store_result": {"type": "boolean", "const": true},
        "candidate_timeout_ms": {"type": "integer", "minimum": 1},
        "old_store_p99_ms": {"type": "integer", "minimum": 1},
        "exceptions_swallowed_and_counted": {"type": "boolean", "const": true},
        "sampling_flag": {"$ref": "#/definitions/flag_name"},
        "sampling_percent_initial": {"type": "number", "minimum": 0, "exclusiveMaximum": 100},
        "mismatch_metric": {"type": "string", "const": "shadow_read_mismatch_ratio"},
        "mismatch_samples_retained": {"type": "boolean", "const": true}
      }
    },
    "flags": {
      "type": "object",
      "required": ["dual_write_on", "shadow_read_on", "read_from_new_on", "write_to_old_off", "runtime_flippable", "reverse_order", "retention_window_days", "read_flipback_rehearsed_before_write_off"],
      "additionalProperties": false,
      "properties": {
        "dual_write_on": {"$ref": "#/definitions/flag_name"},
        "shadow_read_on": {"$ref": "#/definitions/flag_name"},
        "read_from_new_on": {"$ref": "#/definitions/flag_name"},
        "write_to_old_off": {"$ref": "#/definitions/flag_name"},
        "runtime_flippable": {"type": "boolean", "const": true},
        "reverse_order": {
          "type": "array",
          "minItems": 4,
          "maxItems": 4,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["write_to_old_off", "read_from_new_on", "shadow_read_on", "dual_write_on"]}
        },
        "retention_window_days": {"type": "integer", "minimum": 1},
        "read_flipback_rehearsed_before_write_off": {"type": "boolean", "const": true}
      }
    },
    "cutover": {
      "type": "object",
      "required": ["gate_declared_before_shadow", "read_from_new_approver", "write_to_old_off_approver"],
      "additionalProperties": false,
      "properties": {
        "gate_declared_before_shadow": {"type": "boolean", "const": true},
        "gate_evaluation_url": {"type": "string", "format": "uri"},
        "read_from_new_flipped": {"type": "boolean"},
        "read_from_new_approver": {"$ref": "#/definitions/handle"},
        "write_to_old_off_approver": {"$ref": "#/definitions/handle"}
      },
      "if": {"properties": {"read_from_new_flipped": {"const": true}}},
      "then": {"required": ["gate_evaluation_url"]}
    },
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri"}}
  }
}
